===== Households =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Shared household matching: canonicalizes the free-text fields that identify a household
 * (last name and address) so values that differ only in letter case, in the amount of
 * surrounding/internal whitespace, or (for the address) in common street-type
 * abbreviations compare equal. Used to detect when a new owner shares a household with an
 * existing one, and to derive the stable identifier that owners in the same household share.
 */
final class Households {

    private Households() {
    }

    /**
     * Canonicalizes a last name for case-insensitive, whitespace-insensitive comparison:
     * trims the ends, collapses every run of whitespace to a single space and lower-cases
     * the result. Returns an empty string when {@code lastName} is {@code null}.
     */
    private static String normalizeName(String lastName) {
        if (lastName == null) {
            return "";
        }
        return lastName.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    /**
     * Canonicalizes an address using the same normalization applied when an owner is created
     * (see {@link Addresses#normalize(String)}), so household comparisons see the stored,
     * abbreviation-expanded form. Returns an empty string when {@code address} is
     * {@code null}.
     */
    private static String normalizeAddress(String address) {
        String normalized = Addresses.normalize(address);
        return normalized == null ? "" : normalized;
    }

    /**
     * Whether {@code owner} belongs to the household identified by {@code lastName} and
     * {@code address}, comparing the last name and the address in their canonical forms.
     */
    static boolean matches(Owner owner, String lastName, String address) {
        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
                && normalizeAddress(address).equals(normalizeAddress(owner.getAddress()));
    }

    /**
     * The stable identifier shared by every owner in the household identified by
     * {@code lastName} and {@code address}. Derived purely from the canonical household key,
     * so the same household always yields the same id without any coordination.
     */
    static String id(String lastName, String address) {
        String key = normalizeName(lastName) + "\n" + normalizeAddress(address);
        return "H-" + Hashes.upperHexPrefix(key, 12);
    }

    /**
     * The household id a create request resolves to: the shared id of the household it joins
     * when it opts in ({@code sharesHousehold} true) and an existing owner already lives at
     * the same address under the same last name, otherwise an empty string. Mirrors the
     * assignment performed by {@link AssignHousehold}.
     */
    static String resolveHouseholdId(OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return "";
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (matches(existing, request.getLastName(), request.getAddress())) {
                return id(request.getLastName(), request.getAddress());
            }
        }
        return "";
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * When a create request opts into a shared household ({@code sharesHousehold} true) and an
 * existing owner already lives at the same address under the same last name, joins the new
 * owner to that household: every owner in it — the existing members and the new one — is
 * stamped with the same stable {@link Households#id(String, String) household id}. Owners
 * that are not part of a shared household keep a null id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
            OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = Households.id(request.getLastName(), request.getAddress());
        boolean joined = false;
        for (Owner existing : ownerRepository.findAll()) {
            if (Households.matches(existing, request.getLastName(), request.getAddress())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
                joined = true;
            }
        }
        if (joined) {
            owner.setHouseholdId(householdId);
        }
    }
}
===== DetectPossibleDuplicate =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags the new owner as a possible duplicate of an existing one. A create that reaches this
 * step has already cleared the hard identity check ({@link EnsureUniqueIdentity}); it is a
 * <em>possible</em> duplicate when it shares an existing owner's last name and postcode but was
 * given a different telephone (see {@link PossibleDuplicates}). The matching owner's id is
 * recorded so the response can point at it; otherwise the owner is flagged as no duplicate.
 */
public class DetectPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Integer matchId = PossibleDuplicates.matchFor(owner, ownerRepository).orElse(null);
        owner.setPossibleDuplicate(matchId != null);
        owner.setPossibleDuplicateOf(matchId);
    }
}
===== CountHouseholdMembers =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners share the new owner's household. Counts the existing owners with
 * the same {@code householdId} (assigned earlier by {@link AssignHousehold}) and adds one
 * for the owner being created, so the count reflects the household size that results from
 * this create. An owner not sharing a household ({@code householdId} is {@code null}) is a
 * household of one.
 */
public class CountHouseholdMembers {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 1;
        String householdId = owner.getHouseholdId();
        if (householdId != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (householdId.equals(existing.getHouseholdId())) {
                    count++;
                }
            }
        }
        owner.setHouseholdMemberCount(count);
    }
}
===== MembershipLevel =====
package org.springframework.samples.petclinic.model;

/**
 * The owner's membership level: a number from 1 to 3 fixed at creation. It starts at
 * {@link #BASE}, gains a level when an email address is present and another when the owner
 * has no namesakes ({@code namesakeCount} is 0), and is capped at {@link #MAX}. Level 4 is
 * reserved for tenure.
 */
public final class MembershipLevel {

    /** The starting level, before any bonuses. */
    public static final int BASE = 1;

    /** The highest level attainable at creation; level 4 is reserved for tenure. */
    public static final int MAX = 3;

    private MembershipLevel() {
    }

    /**
     * The membership level for the given owner: {@link #BASE}, plus one when an email
     * address is present and one when the owner has no namesakes, capped at {@link #MAX}.
     */
    public static int of(Owner owner) {
        int level = BASE;
        if (owner.hasEmail()) {
            level++;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            level++;
        }
        return Math.min(level, MAX);
    }
}

