===== PossibleDuplicates =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Optional;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Soft duplicate matching: a new owner is a <em>possible</em> duplicate of an existing owner
 * when they share the same last name (compared case-insensitively, ignoring surrounding and
 * internal whitespace) and the same postcode, yet were given a different telephone number.
 *
 * <p>Unlike a hard identity duplicate (see {@link IdentityKeys}), which is rejected outright,
 * a possible duplicate is still created and merely flagged with the id of the owner it
 * resembles. The differing telephone is what keeps it from being a hard duplicate in the first
 * place.
 */
final class PossibleDuplicates {

    private PossibleDuplicates() {
    }

    /**
     * The id of the earliest existing owner the given owner possibly duplicates — same last
     * name and postcode, different telephone — or empty when there is no such owner.
     */
    static Optional<Integer> matchFor(Owner owner, OwnerRepository ownerRepository) {
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (matches(owner, existing) && (match == null || existing.getId() < match.getId())) {
                match = existing;
            }
        }
        return Optional.ofNullable(match).map(Owner::getId);
    }

    private static boolean matches(Owner owner, Owner existing) {
        return samePostcode(owner.getPostcode(), existing.getPostcode())
                && sameLastName(owner.getLastName(), existing.getLastName())
                && !sameTelephone(owner.getTelephone(), existing.getTelephone());
    }

    private static boolean samePostcode(String a, String b) {
        return a != null && b != null && a.trim().equals(b.trim());
    }

    private static boolean sameLastName(String a, String b) {
        return normalizeName(a).equals(normalizeName(b)) && !normalizeName(a).isEmpty();
    }

    private static boolean sameTelephone(String a, String b) {
        return a != null && a.equals(b);
    }

    private static String normalizeName(String name) {
        if (name == null) {
            return "";
        }
        return name.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== EnsureUniqueIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose {@link IdentityKeys identity key} — normalized telephone,
 * email and household id combined — exactly matches an existing owner's. This is the single
 * duplicate check: telephone, email and household are no longer tested independently, so two
 * owners collide only when their whole keys are equal.
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = IdentityKeys.of(request, ownerRepository);
        for (Owner owner : ownerRepository.findAll()) {
            if (identityKey.equals(IdentityKeys.of(owner))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== Hashes =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Shared SHA-256 hashing used to derive stable identifiers from an owner's own fields
 * (the customer code and the household id). Both take a fixed-length upper-case hex prefix
 * of the digest, so the derivation lives here once rather than being copied per caller.
 */
final class Hashes {

    private Hashes() {
    }

    /**
     * The first {@code length} characters of the SHA-256 digest of {@code value}, rendered
     * as upper-case hex over the UTF-8 bytes of the input.
     */
    static String upperHexPrefix(String value, int length) {
        return hex(value).substring(0, length).toUpperCase(Locale.ROOT);
    }

    private static String hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }
}
===== IdentityKeys =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * The single derived key that governs owner duplicate detection. An owner's
 * {@code identityKey} is {@code normalizedTelephone + "|" + (email or empty) + "|" +
 * householdId}, canonicalizing each part the same way it is stored (E.164 telephone,
 * lower-cased email, shared household id). Two owners are duplicates only when their
 * <em>whole</em> keys are equal, so the previously separate telephone, email and household
 * checks are now three parts of one comparison: members of the same household with
 * different telephones have different keys and are both allowed.
 */
public final class IdentityKeys {

    private IdentityKeys() {
    }

    /**
     * The identity key of an existing owner, derived from its stored fields.
     */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * The identity key a create request resolves to, using the household id the owner would
     * be assigned (see {@link Households#resolveHouseholdId}).
     */
    static String of(OwnerFieldsDto request, OwnerRepository ownerRepository) {
        return key(request.getTelephone(), request.getEmail(),
                Households.resolveHouseholdId(request, ownerRepository));
    }

    private static String key(String telephone, String email, String householdId) {
        String normalizedTelephone = telephone == null ? ""
                : Telephones.toE164(telephone).orElse(telephone);
        String normalizedEmail = email == null || email.isBlank() ? "" : Emails.normalize(email);
        String household = householdId == null ? "" : householdId;
        return normalizedTelephone + "|" + normalizedEmail + "|" + household;
    }
}
===== Postcodes =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.CityRegion;

/**
 * Postcode validity: a postcode must be exactly four digits, and when the owner's city has a
 * known region (see {@link CityRegion}) it must fall within that region's pinned inclusive
 * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
 * four-digit postcode.
 */
final class Postcodes {

    private Postcodes() {
    }

    /**
     * Whether {@code postcode} is valid for {@code city}: it must be exactly four digits and,
     * when the city's region has a pinned range, fall inside that range. Cities with no known
     * region accept any four-digit postcode.
     */
    static boolean isValidForCity(String postcode, String city) {
        if (postcode == null || !postcode.matches("\\d{4}")) {
            return false;
        }
        int[] range = CityRegion.rangeOf(CityRegion.localityOf(city));
        if (range == null) {
            return true;
        }
        int value = Integer.parseInt(postcode);
        return value >= range[0] && value <= range[1];
    }
}

